def transform(grid):
    n = len(grid)
    if n == 0: return [[0]]

    # Determine background color (least frequent)
    colors = {}
    for r in range(n):
        for c in range(n):
            colors[grid[r][c]] = colors.get(grid[r][c], 0) + 1
    bg = min(colors, key=colors.get)

    output_size = 2 * n
    output = [[0] * output_size for _ in range(output_size)]

    # Fill colors from input corners for each quadrant
    fills = [grid[0][0], grid[0][1], grid[1][0], grid[1][1]]

    # Transform function helper
    def transform_quadrant(base_grid, flip_h, flip_v, fill_color):
        quad = [[0]*n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                tr = n - 1 - r if flip_v else r
                tc = n - 1 - c if flip_h else c
                val = base_grid[tr][tc]
                if val == bg:
                    val = fill_color
                quad[r][c] = val
        return quad

    # Process 4 quadrants
    for qr in range(2):
        for qc in range(2):
            flip_h = (qc == 1)
            flip_v = (qr == 1)
            fill_color = fills[qr * 2 + qc]

            for r in range(n):
                for c in range(n):
                    output[qr*n + r][qc*n + c] = transform_quadrant(grid, flip_h, flip_v, fill_color)[r][c]

    return output
